import React, { useEffect, useState } from 'react';
import Header from './components/Header';
import TareaForm from './components/TareaForm';
import TareaList from './components/TareaList';
import { obtenerTareas, eliminarTarea } from './services/api';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function App() {
  const [tareas, setTareas] = useState([]);
  const [filtro, setFiltro] = useState('');

  const cargarTareas = () => {
    obtenerTareas().then(setTareas);
  };

  const handleEliminar = async (id) => {
    if (window.confirm("¿Estás seguro de eliminar esta tarea?")) {
      await eliminarTarea(id);
      toast.info("Tarea eliminada");
      cargarTareas();
    }
  };

  useEffect(() => {
    cargarTareas();
  }, []);

  return (
    <div className="min-h-screen bg-[#f8f9fa] text-gray-900">
      <header className="bg-[#1C2E65] text-white p-4 shadow-md">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <img src="/qh-logo.png" alt="Quito Honesto" className="h-12 w-auto" />

          <div className="text-center flex-1">
            <h1 className="text-xl sm:text-2xl font-bold">Gestión de Tareas Municipales</h1>
            <p className="text-sm sm:text-base text-blue-100">
              Plataforma de tareas para entidades del Municipio de Quito
            </p>
          </div>

          <img src="/alcaldia-logo.png" alt="Alcaldía de Quito" className="h-10 w-auto" />
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 py-6">
        <div className="flex flex-col lg:flex-row gap-6">

          {/* Formulario a la izquierda */}
          <div className="lg:w-1/3 bg-white p-4 rounded shadow border border-blue-100">
            <TareaForm onTareaCreada={cargarTareas} toast={toast} />
          </div>

          {/* Lista de tareas a la derecha */}
          <div className="lg:w-2/3">
            <input
              type="text"
              placeholder="Buscar tareas..."
              value={filtro}
              onChange={(e) => setFiltro(e.target.value)}
              className="w-full p-2 mb-4 border border-blue-300 rounded"
            />
            <TareaList
              tareas={tareas.filter(t =>
                t.descripcion.toLowerCase().includes(filtro.toLowerCase()) ||
                t.entidadMunicipalNombre.toLowerCase().includes(filtro.toLowerCase())
              )}
              onEliminar={handleEliminar}
              toast={toast}
            />
          </div>
        </div>
      </div>
      <ToastContainer position="top-center" autoClose={3000} />
    </div>
  );
}

export default App;
